package server

func init() {
	pages["admin_operations"] = `{{define "content"}}
<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h1 class="mb-1">Operations</h1><p class="text-muted mb-0">Live concentrator state and administrative maintenance.</p></div><a class="btn btn-outline-primary" href="/admin/operations">Refresh</a></div>
<section class="card shadow-sm mb-4"><div class="card-body"><h2 class="h4">In-memory control state</h2><div class="row g-3"><div class="col-md"><strong>Policy snapshot</strong><br>Version {{.PolicyVersion}} · {{.PolicyRouters}} routers · {{.PolicyBlocks}} blocked owner pairs</div><div class="col-md"><strong>Instance lease</strong><br>{{if .Draining}}Draining{{else}}Healthy{{end}} · {{.HeartbeatFailures}} heartbeat failures<br><small>last success {{date .LastHeartbeat}}</small></div><div class="col-md"><strong>Persistence</strong><br>{{.WriteFailures}} exhausted writes · {{.RouterLogStale}} stale router logs discarded<br><small>Circuit history: {{.HistoryPending}} pending · {{.HistoryArchived}} archived · {{.HistoryPersisted}} persisted · {{.HistoryRetries}} retries · {{.HistoryFailed}} failed</small></div></div></div></section>
<section class="card shadow-sm mb-4"><div class="card-body"><h2 class="h4">Asynchronous queues</h2><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Queue</th><th>Current</th><th>High-water</th><th>Limit</th><th>Dropped</th></tr></thead><tbody><tr><td>Router flow/audit logs</td><td>{{.RouterLogQueue.Depth}} records / {{.RouterLogQueue.Bytes}} bytes</td><td>{{.RouterLogQueue.HighWater}} records / {{.RouterLogQueue.HighWaterBytes}} bytes</td><td>{{.RouterLogQueue.Limit}} records / {{.RouterLogQueue.ByteLimit}} bytes</td><td>{{.RouterLogQueue.Dropped}}</td></tr><tr><td>SNA circuit history</td><td>{{.HistoryQueue.Depth}} records</td><td>{{.HistoryQueue.HighWater}} records</td><td>{{.HistoryQueue.Limit}} records</td><td>{{.HistoryQueue.Dropped}}</td></tr></tbody></table></div></div></section>
<section class="card shadow-sm mb-4"><div class="card-body"><h2 class="h4">Maintenance tasks</h2><p class="text-muted">Scheduled and manual runs use the same implementation. Results are retained across restarts.</p><div class="table-responsive"><table class="table table-striped align-middle mb-0"><thead><tr><th>Task</th><th>Schedule</th><th>Last run</th><th>Status</th><th>Result</th><th></th></tr></thead><tbody>{{range .Tasks}}<tr><td><strong>{{.Title}}</strong><br><small class="text-muted">{{.Description}}</small></td><td>{{.Schedule}}</td><td>{{date .StartedAt}}{{if .FinishedAt}}<br><small>finished {{date .FinishedAt}}</small>{{end}}{{if .Trigger}}<br><small>{{.Trigger}}{{if .TriggeredBy}} by {{.TriggeredBy}}{{end}}</small>{{end}}</td><td>{{if eq .Status "success"}}<span class="badge text-bg-success">Success</span>{{else if eq .Status "failed"}}<span class="badge text-bg-danger">Failed</span>{{else if eq .Status "running"}}<span class="badge text-bg-warning">Running</span>{{else}}<span class="badge text-bg-secondary">Never run</span>{{end}}</td><td>{{if .Result}}{{.Result}}{{else}}—{{end}}</td><td><form method="post" action="/admin/operations/{{.Name}}/run"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="btn btn-outline-primary btn-sm" {{if eq .Status "running"}}disabled{{end}}>Run now</button></form></td></tr>{{end}}</tbody></table></div></div></section>
{{end}}`
}
